typedef unsigned int u_int;

enum WaveStageEnum
{
	WAVE_StageBuilding,
	WAVE_StageStable,
	WAVE_StageSubsiding,
	WAVE_StageMax
};

enum WavePerturbStageEnum
{
	WAVE_PerturbStageNone,
	WAVE_PerturbStageDo,
	WAVE_PerturbStageHold,
	WAVE_PerturbStageCollapse,
	WAVE_PerturbStageWait,
	WAVE_PerturbStageUndo,
	WAVE_PerturbStageMax
};

struct WavePartition
{
	u_int N;
	float *guide;
	float *guidestep;
	float *weight;
};

class WaveBasePerturbClass
{
public:
	float (&duration)[WAVE_PerturbStageMax], start[WAVE_PerturbStageMax];
	WavePartition partition;

	bool Enabled(void) { return enabled; }

	virtual void Init(void) = 0;
	virtual float WorldToProfile(float worldx) = 0;

protected:
	const int &enabled;

private:
	float guide[32];
	float guidestep[32];
	float weight[32];
};

class WavePerturbStairstepClass
{
public:
	bool Enabled(void) { return enabled; }
	virtual float WorldToProfile(float worldx);
private:
	int enabled;
};

struct WaveDebugStruct
{
	int values[65];
	int StaticWave;
};

extern float WAVE_MeshMinX;
extern float WAVE_MeshMaxX;
extern bool WAVE_LeftBreaker;
extern WaveDebugStruct WaveDebug;
extern WavePerturbStageEnum WAVE_PerturbStage;
extern WaveBasePerturbClass *WAVE_Perturb;
extern WavePerturbStairstepClass WAVE_PerturbStairstep;
extern WaveStageEnum WAVE_Stage;
extern float WAVE_StageProgress;

template <class T> inline const T& min(const T& a, const T& b) { return b < a ? b : a; }
template <class T> inline const T& max(const T& a, const T& b) { return a < b ? b : a; }

static float WAVE_WorldToProfile(float x)
{
	if (WAVE_LeftBreaker)
	{
		x = WAVE_MeshMinX + WAVE_MeshMaxX - x;
	}

	if (WaveDebug.StaticWave)
	{
		return x;
	}

	if (WAVE_PerturbStage != WAVE_PerturbStageNone && WAVE_Perturb->Enabled())
	{
		x = WAVE_Perturb->WorldToProfile(x);
		if (x < WAVE_MeshMinX) x = WAVE_MeshMinX;
		else if (x > WAVE_MeshMaxX) x = WAVE_MeshMaxX;
	}

	if (WAVE_PerturbStairstep.Enabled())
	{
		x = WAVE_PerturbStairstep.WorldToProfile(x);
		if (x < WAVE_MeshMinX) x = WAVE_MeshMinX;
		else if (x > WAVE_MeshMaxX) x = WAVE_MeshMaxX;
	}

	float a = (x - WAVE_MeshMinX) / (WAVE_MeshMaxX - WAVE_MeshMinX);	// from 0 to 1 over width of wave, in reverse time

	switch (WAVE_Stage)	// these are linked to the subdivision methods in WAVE_ComputeGrid
	{
	case WAVE_StageBuilding:
/*
		// Old method
		a = 1 - (1 - a) * WAVE_StageProgress;
*/
		// New method
		a = min(1.f, a + 1 - WAVE_StageProgress);
		break;
	case WAVE_StageSubsiding:
/*
		// Old method
		a = a * (1 - WAVE_StageProgress);
*/
		// New method
		a = max(0.f, a - WAVE_StageProgress);
		break;
	default:
		break;
	}

	return (WAVE_MeshMaxX - WAVE_MeshMinX) * a + WAVE_MeshMinX;
}
